let intervalID = context.get("intervalID");
let prevState = context.get("prevState") || [];

// Helper to convert HH:MM to hour (rounds up at 30 minutes)
const getHour = (timeStr) => {
    const [h, m] = timeStr.split(":").map(Number);
    return h + (m >= 30 ? 1 : 0);
};

// === Input from payload ===
const { departure_time, arrival_time, weekend, season } = msg.payload || {};
const leaveHour = departure_time ? getHour(departure_time) : 9;
const returnHour = arrival_time ? getHour(arrival_time) : 18;

// Sleep/wake times
const sleepHour = 22;
const wakeHour = 6;

// === Fan burst hours by season ===
const fanBurstsBySeason = {
    Summer: [9, 10, 15, 16, 20, 21],
    Fall:   [9, 10, 14, 15, 19, 20],
    WinterSpring: [9, 10, 14, 15, 19, 20]
};

// Normalize season input from payload
let normalizedSeason = "Summer";
if (season) {
    const s = season.toLowerCase();
    if (s.includes("winter") || s.includes("spring")) {
        normalizedSeason = "WinterSpring";
    } else if (s.includes("fall")) {
        normalizedSeason = "Fall";
    } else if (s.includes("summer")) {
        normalizedSeason = "Summer";
    }
}

const fanBurstHours = fanBurstsBySeason[normalizedSeason];

// === Helper functions ===
const isHome = (hour) => weekend || hour < leaveHour || hour >= returnHour;
const isAwake = (hour) => hour >= wakeHour && hour < sleepHour;
const isMiddayWeekend = (hour) => weekend && hour >= 10 && hour <= 16;

// === Create dynamic schedule ===
const dynamicSchedule = {};
ALL_TOPICS.forEach(topic => {
    dynamicSchedule[topic] = [];

    // Skip control here, it only fires once at 8:00
    if (CONTROL_TOPICS.includes(topic)) return;

    for (let hour = 0; hour < 24; hour++) {
        const home = isHome(hour);
        const awake = isAwake(hour);

        // Fans: always on during specified burst hours
        if (FAN_TOPICS.includes(topic)) {
            if (fanBurstHours.includes(hour)) {
                dynamicSchedule[topic].push(hour);
            }
            continue;
        }

        let activeChance = 0;
        if (topic.startsWith("Smart_Devices") && home && awake) {
            activeChance = 0.9;
        } 
        else if ((topic.startsWith("TV") || topic.includes("Oven")) && home && awake) {
            activeChance = 0.9;
        } 
        else if (topic.includes("Microwaves") && home && awake) {
            activeChance = [7, 12, 18].includes(hour) ? 0.6 : 0.1;
        } 
        else if (topic.includes("Dishwasher") && hour === 19 && home && awake) {
            activeChance = 0.9;
        } 
        else if ((topic.toLowerCase().includes("wash") || topic.includes("dryer")) && hour === 10 && home && awake) {
            activeChance = 0.9;
        } 
        else if (topic.includes("Fridge")) {
            activeChance = 1; // Always on
        } 
        else if (LED_TOPICS.includes(topic) && home && awake) {
            activeChance = 0.9;
        }

        // Weekend midday boost
        if (isMiddayWeekend(hour)) {
            activeChance = Math.min(activeChance + 0.3, 1);
        }

        if (Math.random() < activeChance) {
            dynamicSchedule[topic].push(hour);
        }
    }

    // Convert hours to ranges
    const hours = dynamicSchedule[topic];
    const ranges = [];
    let start = null;
    for (let i = 0; i < hours.length; i++) {
        if (start === null) start = hours[i];
        if (hours[i + 1] !== hours[i] + 1) {
            ranges.push([start, hours[i] + 1]);
            start = null;
        }
    }
    dynamicSchedule[topic] = ranges;
});

// === Simulation start ===
if (msg.payload && !simRunning) {
    node.warn("Scheduled simulation started.");
    let hour = 0;

    intervalID = setInterval(() => {
        let msgs = [];

        // Determine devices ON at this hour
        let currentOn = ALL_TOPICS.filter(topic => {
            const intervals = dynamicSchedule[topic] || [];
            return intervals.some(([start, end]) => hour >= start && hour < end);
        });

        if (hour === 8) {
            msgs.push({ topic: "control", payload: "start" });
        }

        if (hour === 0) {
            // Send initial full state (excluding control)
            ALL_TOPICS.forEach(topic => {
                if (CONTROL_TOPICS.includes(topic)) return;
                const isOn = currentOn.includes(topic);
                if (isOn) {
                    const isFan = FAN_TOPICS.includes(topic);
                    msgs.push({ topic, payload: isFan ? 2 : 1 });
                } else {
                    msgs.push({ topic, payload: 0 });
                }
            });
        } else {
            // Send only changes (excluding control)
            let turnedOff = prevState.filter(topic => !currentOn.includes(topic));
            let turnedOn = currentOn.filter(topic => !prevState.includes(topic));

            turnedOff.forEach(topic => msgs.push({ topic, payload: 0 }));
            turnedOn.forEach(topic => {
                const isFan = FAN_TOPICS.includes(topic);
                msgs.push({ topic, payload: isFan ? 2 : 1 });
            });
        }

        // Send messages
        msgs.forEach(m => node.send(m));

        // Update state
        prevState = currentOn;
        context.set("prevState", currentOn);

        hour++;

        // End simulation
        if (hour >= TOTAL_HOURS) {
            node.warn("Schedule simulation complete.");
            ALL_TOPICS.forEach(topic => {
                if (CONTROL_TOPICS.includes(topic)) return; // don't reset control
                node.send({ topic, payload: 0 });
            });
            clearInterval(context.get("intervalID"));
            context.set("intervalID", null);
            context.set("simRunning", false);
            context.set("prevState", []);
        }
    }, INTERVAL_MS);

    context.set("intervalID", intervalID);
    context.set("simRunning", true);
}

return null;
